import{scheduleActivityHTML,newScheduleNotifications}from'./schedule-activity.mjs';
import{scheduleTypedData}from'./schedule.mjs';
import{informationFooter,informationLinks}from'./information.mjs';
import{grantfoldToken,gfldTiersText,tokenLink}from'./token.mjs';
import{commission,orderTotal,consentTypedData,withdrawalTypedData}from'./commission.mjs';
import{categories,catalog,initialState,dollars,ledger}from'./core.mjs';
import{liveMarket,usdg,liveHeld,liveTotals}from'./payment.mjs';
import{connectLiveWallet,signLiveOrder}from'./live.js';
import{signInWithWallet}from'./wallet-auth.js';
const $=s=>document.querySelector(s),app=$('#app'),legacyKey='tab-rh-study-v1';
function requestedTab(){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('tab');return ['assistant','shop','approvals','activity','settings','connect'].includes(value)?value:null;}
let state=initialState(),tab=requestedTab()||'assistant',howStep=0,lastFocus=null,busy=false,networkBusy=false,ready=false,loading=false,accountError=null,sessionUser=null,revision=-1,skipLegacy=false,feePolicy=null,schedulingCapabilities=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rememberSelection(){try{localStorage.setItem('grantfold:selected-card',state.selected);}catch{}}
function applySnapshot(data){if(data.revision<revision)return;const selected=state.selected;state=data.state;revision=data.revision;sessionUser=data.user;try{const preferred=localStorage.getItem('grantfold:selected-card');if(state.cards.some(c=>c.id===preferred))state.selected=preferred;else if(state.cards.some(c=>c.id===selected))state.selected=selected;}catch{}}
async function apiRequest(path,body,key){let response;try{response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{'X-Grantfold-Client':'browser',...(body!==undefined?{'Content-Type':'application/json'}:{}),...(key?{'Idempotency-Key':key}:{})},body:body===undefined?undefined:JSON.stringify(body)});}catch{const e=Error('Connection lost. Reload to recover the previous request safely.');e.uncertain=true;throw e;}
 let data;try{data=await response.json();}catch{const e=Error('Account service is unavailable. Reload to check your request.');e.uncertain=true;throw e;}
 if(!response.ok){const e=Error(data.error?.message||'Account request failed.');e.status=response.status;e.code=data.error?.code;e.uncertain=response.status>=500||e.code==='account_busy';throw e;}return data;}
const pendingKey=()=>sessionUser?'grantfold:pending:'+sessionUser.id:null;
function pendingRequest(){try{return JSON.parse(sessionStorage.getItem(pendingKey())||'null');}catch{return null;}}
function savePending(value){try{if(value)sessionStorage.setItem(pendingKey(),JSON.stringify(value));else sessionStorage.removeItem(pendingKey());}catch{}}
async function mutate(body,path='/api/actions'){if(networkBusy)throw Error('Your previous request is still processing.');if(!ready)throw Error('Load your account before making changes.');networkBusy=true;app.setAttribute('aria-busy','true');const key=crypto.randomUUID();savePending({key,body,path});
 try{const data=await apiRequest(path,body,key);applySnapshot(data);savePending(null);return data.effect;}catch(e){if(e.uncertain){ready=false;accountError=e;closeModal();render();}else{savePending(null);if(e.status===401){ready=false;accountError=e;closeModal();render();}}throw e;}finally{networkBusy=false;app.removeAttribute('aria-busy');}}
async function loadAccount(){if(loading)return;loading=true;accountError=null;render();try{const auth=await apiRequest('/api/session');if(!auth.authenticated){const e=Error('Connect your wallet to open your Grantfold account.');e.status=401;throw e;}sessionUser=auth.user;feePolicy=auth.fees;schedulingCapabilities=auth.scheduling;let legacy=null;try{if(!skipLegacy&&!localStorage.getItem('grantfold:imported:'+sessionUser.id))legacy=JSON.parse(localStorage.getItem(legacyKey)||'null');}catch{}
 const data=await apiRequest('/api/account/bootstrap',{legacy});applySnapshot(data);try{localStorage.setItem('grantfold:imported:'+sessionUser.id,'1');}catch{}
 const pending=pendingRequest();if(pending?.key&&pending.body){try{applySnapshot(await apiRequest(['/api/schedule/prepare','/api/schedule/enable','/api/schedule/pause','/api/live/quote','/api/live/prepare','/api/live/pay','/api/live/cancel','/api/live/check','/api/live/fee_transaction','/api/live/fee_declined','/api/live/fee_check','/api/agent/prepare','/api/agent/enable','/api/agent/revoke','/api/agent/approve','/api/agent/check','/api/agent/withdraw_prepare','/api/agent/withdraw','/api/agent/withdraw_check','/api/agent/withdraw_cancel'].includes(pending.path)?pending.path:'/api/actions',pending.body,pending.key));savePending(null);}catch(e){if(!e.uncertain)savePending(null);throw e;}}
 applySnapshot(await apiRequest('/api/account'));ready=true;
 }catch(e){accountError=e;ready=false;}finally{loading=false;render();}}
function accountGate(){
 const signIn=accountError?.status===401;
 const action=loading?'':signIn?'<button class="btn" data-action="wallet-login">Connect wallet</button>':'<button class="btn secondary" data-action="retry-account">Retry account connection</button>';
 return`${appHead()}<main class="section" style="padding-top:25px"><div class="empty-state"><span>${loading?'◷':signIn?'G':'!'}</span><h2>${loading?'Loading your account…':signIn?'Connect your wallet':'Your account needs attention'}</h2><p>${esc(signIn?'Sign a login message to open your Grantfold account. Purchases use a separate spending consent.':accountError?.message||'Opening your saved cards, rules and activity.')}</p>${action}${accountError?.code==='invalid_backup'?'<p>Your browser backup remains unchanged.</p><button class="mini-link" data-action="skip-backup">Start a fresh sandbox</button>':''}<p style="font-size:11px;margin-top:20px">${informationLinks()}</p></div></main>`;
}

const card=()=>state.cards.find(c=>c.id===state.selected)||state.cards[0],brand=(white=false)=>`<img src="assets/grantfold-mark${white?'-white':''}.svg" alt=""><span>Grantfold</span>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function cardArt(name='Research agent',balance=15000,cls=''){return`<div class="agent-card ${cls}"><div class="card-top"><span class="brand">${brand(true)}</span><span>${esc(name)}</span></div><div class="card-chip"></div><div class="card-bottom"><div><small>Available demo balance</small><strong>${dollars(balance)}</strong></div><span>Robinhood Chain<br>Agent spending</span></div></div>`;}
function nav(){return`<div class="nav-wrap"><header class="nav"><a href="#/" class="brand" aria-label="Grantfold home">${brand()}</a><nav class="nav-links" aria-label="Main navigation"><a href="#/" data-scroll="top">Home</a><a href="#features" data-scroll="features">AI agents</a><a href="#how" data-scroll="how">How it works</a><a href="#faq" data-scroll="faq">FAQ</a></nav><a href="#/app" class="btn">Try the demo</a><button class="icon-button menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">☰</button></header><nav class="mobile-menu" aria-label="Mobile navigation"><a href="#features" data-scroll="features">AI agents</a><a href="#how" data-scroll="how">How it works</a><a href="#faq" data-scroll="faq">FAQ</a></nav></div>`;}
function phone(){return`<div class="phone" aria-hidden="true"><div class="phone-status"><span>9:41</span><span>▮▮  ▰</span></div><div class="phone-app-top"><span class="phone-icon"><img src="assets/grantfold-mark-white.svg" alt=""></span><b>Your AI</b><small>card · $150</small></div><div class="phone-bubble">Get me $25 of compute<br>for my research agent.</div><div class="phone-receipt"><span class="check">✓</span><b>Agent compute</b><p>Purchased within your limits.<br>Receipt delivered to your agent.</p><div class="phone-code">DEMO · $25.00</div></div><div class="phone-input">Ask your AI… <span>✦</span></div></div>`;}
function footer(){return informationFooter();}
function home(){return`${nav()}<main id="top"><section class="hero"><span class="pill"><i class="network-dot"></i> Cards for agents on Robinhood Chain</span><h1>Give your AI a card.<br>Let it do the shopping.</h1><p>A separate budget for every agent. Set what it may spend, tell it what you need, and stay in control of every purchase.</p><div class="hero-actions"><a class="btn" href="#/app">Try the demo</a><a class="btn secondary" href="#how" data-scroll="how">How it works</a></div><span class="hero-note">Try demo funds. Buy a live market overview with USDG.</span><div class="hero-product">${cardArt('Research agent',15000,'hero-card')}${phone()}<div class="float-limit"><small>You set the rules</small><b>$50 per purchase</b><p style="font-size:10px;margin-top:7px;color:#929c87">Ask me above $25</p></div><div class="float-approval"><span>✓</span><div>Always within your limits<small>You control the spending.</small></div></div></div></section><section class="partners"><p>Designed around the tools your agents use</p><div class="partner-logos"><span>✳ ChatGPT</span><span>✹ Claude</span><span>⌘ Cursor</span><span>▰ Robinhood Chain</span></div></section><section class="section" id="features"><div class="section-title"><p class="eyebrow">For your AI agents</p><h2>Tell it what to buy.<br>You set the boundaries.</h2><p class="section-sub">A card for the task. A budget you control.</p></div><div class="feature-grid"><article class="feature"><div class="feature-scene"><div class="mini-message">Get me $10 of RPC credits.<small>Purchased. Receipt ready. ✓</small></div></div><h3>Ask in the app</h3><p>Choose a service or type a request. The Assistant buys live market overviews from your funded agent wallet and also supports demo purchases.</p></article><article class="feature"><div class="feature-scene"><div class="mini-connect"><span>✳</span><span>✹</span><span>⌘</span><small>One card. One set of rules.</small></div></div><h3>One card per agent</h3><p>Keep research, coding and shopping budgets separate. Each agent has its own balance and permissions.</p></article><article class="feature"><div class="feature-scene"><div class="mini-rules"><div><span>Per purchase</span><b>$50</b></div><div><span>Per day</span><b>$100</b></div><div><span>Ask me above</span><b>$25</b></div></div></div><h3>Your limits, enforced</h3><p>Large purchases wait for your approval. Pending orders reserve their balance until you decide.</p></article></div></section><section class="section product-section"><div class="product-stack">${cardArt('Coding agent',5000,'back')}${cardArt('Research agent',15000,'front')}</div><div><p class="eyebrow">Your agent’s spending account</p><h2>One card per agent.<br>One set of rules.</h2><p class="section-sub">Give your AI the amount it needs for the job. Keep everything else in your own wallet.</p><div class="product-points"><div><b>Balance. Held. Spent.</b><p>See what’s available, what’s waiting for approval and what has already been used.</p></div><div><b>Freeze it in one tap.</b><p>Pause new purchases whenever you want. Your existing receipts stay available.</p></div></div><a href="#/app" class="btn secondary small" style="margin-top:26px">Create an agent card</a></div></section><section class="how-section" id="how"><div class="section"><div class="section-title"><p class="eyebrow">How it works</p><h2>Fund. Set the rules. Ask.</h2><p class="section-sub">Try the whole flow, from budget to receipt.</p></div><div class="step-tabs" role="tablist" aria-label="How it works">${['Fund','Set rules','Shop'].map((x,i)=>`<button class="step-tab ${i===howStep?'active':''}" data-how="${i}" role="tab" aria-selected="${i===howStep}">${x}</button>`).join('')}</div><div id="how-panel">${howPanel()}</div></div></section><section class="section" id="faq"><div class="section-title"><p class="eyebrow">Before your first card</p><h2>A few things to know.</h2></div><div class="faq-list"><details><summary>Is this a real payment card?</summary><p>This is an interactive design study for Robinhood Chain. Card balances and demo purchases are simulated. Live market overviews can be paid for separately in USDG on Robinhood Chain. There is no bank card issuer or real gift code.</p></details><details><summary>What can I try?</summary><p>Create agent cards, add demo funds, set category and spending limits, make a sample purchase, approve or decline it and inspect the receipt.</p></details><details><summary>Can an agent spend more than I allow?</summary><p>The demo checks the per-purchase limit, daily spending, pending holds, available balance, allowed category and frozen state. Orders are all-or-nothing; it never substitutes a smaller purchase.</p></details><details><summary>Does it connect to ChatGPT or Claude?</summary><p>Use the Assistant on this site to buy live market overviews through your funded agent wallet. External AI clients are not connected to this Vercel version. Other catalog items remain demos.</p></details><details><summary>What is GFLD?</summary><p>Grantfold (GFLD) on Robinhood Chain: ${tokenLink()} <code style="overflow-wrap:anywhere">${grantfoldToken.address}</code>. Holder service fees: ${gfldTiersText}. Base fee: 5%; provider price and gas are separate. For agents, the linked owner wallet’s balance counts. Each new quote shows the applied rate. No token spending approval or staking is required. Token ownership does not promise returns. <a href="/terms">Read the terms</a>.</p></details><details><summary>Will my cards stay here?</summary><p>Sign in with your wallet to keep your cards, settings and purchases across devices. Your login signature is separate from spending consent. Demo balances stay simulated; live orders have separate USDG receipts.</p></details></div></section><section class="closing"><h2>Your AI.<br>Your rules.</h2><a href="#/app" class="btn">Give your agent a card</a></section></main>${footer()}`;}
function howPanel(){const data=[{title:'Give it a budget.',text:'Add demo funds to an agent card. Start with a small amount, and keep the rest outside its reach.',label:'Research agent',value:'$150.00',left:'Demo funds',right:'Ready to use'},{title:'Make the rules yours.',text:'Choose categories, a per-purchase limit and a daily maximum. Decide the amount above which your agent needs to ask.',label:'Spending rules',value:'$50 / buy',left:'Approval above',right:'$25.00'},{title:'Ask. Review. Receive.',text:'Choose an item from the demo shop. Approve a larger purchase and open the receipt when it completes.',label:'Agent compute',value:'Purchased',left:'Sample receipt',right:'DEMO · $25.00'}][howStep];return`<div class="how-panel"><div><h3>${data.title}</h3><p>${data.text}</p><a href="#/app" class="btn secondary small" style="margin-top:22px">Try this step</a></div><div class="how-visual"><div class="v-title">${data.label}</div><div class="v-value">${data.value}</div><div class="v-row"><span>${data.left}</span><b>${data.right}</b></div></div></div>`;}
function appHead(){return`<header class="app-head"><a href="#/" class="brand" aria-label="Grantfold home">${brand()}</a><div class="app-head-right"><span class="network"><i class="network-dot"></i> Robinhood Chain</span><a href="#/">Back to home</a></div></header><div class="demo-bar"><span class="demo-badge">Sandbox</span><span>Demo cards and saved history. Live market overviews are paid separately from your wallet in USDG.</span></div>`;}
function cardRail(){return`<aside class="card-rail"><div class="rail-top"><span>Agent cards <span style="color:#a7b69a">${state.cards.length}/10</span></span><button data-action="new-card">＋ New</button></div><div class="cards-list">${state.cards.map(c=>`<button class="card-choice ${c.id===card().id?'selected':''} ${c.frozen?'frozen':''}" data-card="${esc(c.id)}" aria-label="Select ${esc(c.name)}" aria-pressed="${c.id===card().id}"><div class="agent-card"><div class="card-top"><span class="brand">${brand(true)}</span><span>${esc(c.name)}</span></div><div class="card-bottom"><div><small>${c.frozen?'Frozen':'Available demo balance'}</small><strong>${dollars(ledger(state,c.id).available)}</strong></div><span>Robinhood<br>Chain</span></div></div></button>`).join('')}</div><div class="rail-help"><b>A budget for each agent.</b>Demo balances are simulated. Live purchases use a separately funded wallet.<p style="margin-top:14px">Live market orders use your own wallet.</p></div></aside>`;}
function renderApp(){const c=card(),l=ledger(state,c.id),pending=state.orders.filter(o=>o.cardId===c.id&&o.status==='pending').length+(state.liveOrders||[]).filter(o=>o.cardId===c.id&&liveHeld(o)).length;return`${appHead()}<main class="app-layout">${cardRail()}<section class="account"><div class="account-title"><div><h1>${esc(c.name)}</h1><p>A spending account for your agent.</p></div><span class="state ${c.frozen?'frozen':''}"><i class="network-dot"></i> ${c.frozen?'Frozen':'Card active'}</span></div>${c.frozen?'<p class="frozen-banner">This card is frozen. Unfreeze it to make or approve purchases.</p>':''}<section class="balance-card" aria-label="Card balance"><div class="balance-item"><small>Available demo balance</small><strong>${dollars(l.available)}</strong></div><div class="balance-item"><small>On hold</small><strong>${dollars(l.held)}</strong></div><div class="balance-item"><small>Spent today · UTC</small><strong>${dollars(l.spent)}</strong></div><div class="balance-actions"><button class="btn small" data-action="fund">Add funds</button><button class="btn secondary small" data-action="freeze">${c.frozen?'Unfreeze':'Freeze'}</button></div></section><nav class="account-tabs" aria-label="Agent card sections">${[['assistant','Assistant'],['shop','Shop'],['approvals','Approvals'],['activity','Activity'],['settings','Rules'],['connect','Connect AI']].map(([v,label])=>`<button class="account-tab ${tab===v?'active':''}" data-tab="${v}" aria-current="${tab===v?'page':'false'}">${label} ${v==='approvals'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div id="account-content">${(state.liveOrders||[]).some(o=>o.cardId===c.id)?`<div class="hint-box" style="margin:0 0 24px"><b>Live wallet spending · Robinhood Chain</b>${usdg(liveTotals(state,c.id).spent)} spent today · ${usdg(liveTotals(state,c.id).held)} reserved or being checked. Live orders use this card’s category and purchase/day limits; demo funds are separate.</div>`:''}${tab==='assistant'?assistant(c):tab==='shop'?shop():tab==='approvals'?orders(c,true):tab==='activity'?orders(c,false):tab==='settings'?settings(c):connector()}</div><p class="app-fineprint">Demo funds are simulated. Live market orders use your wallet in USDG on Robinhood Chain. Agents use a separate consented wallet in Assistant. <a href="#" data-action="wallet-signout">Disconnect wallet</a> · ${informationLinks()}</p></section></main>`;}
function activityPanel(){const scheduled=scheduleActivityHTML(state,card().id,true);if(scheduled)return scheduled;const list=state.activity.slice(0,4);return`<section class="panel"><div class="panel-title"><h2>Activity</h2><span>Demo session</span></div><div class="activity-list">${list.length?list.map(a=>`<div class="activity-item"><span class="activity-dot">${a.kind==='pending'?'◷':a.kind==='declined'||a.kind==='cancelled'?'−':a.kind==='fund'?'+':'✓'}</span><div>${esc(a.text)}<small>${new Date(a.time).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})} · demo</small></div></div>`).join(''):'<div class="activity-item"><span class="activity-dot">✓</span><div>Your research card is ready.<small>$150 in sample balance</small></div></div>'}</div></section>`;}
function assistant(c){const messages=state.messages?.[c.id]||[];return`<div class="workspace"><section class="panel"><div class="chat-heading"><span class="phone-icon"><img src="assets/grantfold-mark-white.svg" alt=""></span><div><b>Your spending assistant</b><small>It buys with this card’s rules.</small></div></div><div class="chat-messages" id="chat-messages">${messages.length?messages.map(m=>m.type==='user'?`<div class="user-message">${esc(m.text)}</div>`:`<div class="assistant-message">${esc(m.text)}${m.liveOrderId?`<div class="order-actions"><button class="mini-link" data-live-open="${esc(m.liveOrderId)}">${findLive(m.liveOrderId)?.status==='completed'?'View report & receipt':'Review live purchase'}</button></div>`:m.connectAgent?'<div class="order-actions"><button class="mini-link" data-tab="connect">Set up agent wallet</button></div>':''}</div>`).join(''):`<p class="chat-intro">Ask me to buy a live market overview, check your agent’s balance or GFLD fee, or pause new agent purchases.</p><div class="chat-examples"><button data-request="Buy a live market overview">Buy a live market overview</button><button data-request="Check agent balance">Check agent balance</button><button data-request="Check my GFLD fee">Check my GFLD fee</button><button data-request="Pause agent">Pause agent</button><button data-schedule-open>Schedule daily purchase</button><button data-request="Buy a $40 market data pass">Get a $40 market data pass</button><button data-request="Buy $25 of compute">Give my agent $25 of compute</button></div>`}${busy?'<div class="assistant-message" role="status">Checking this card’s rules…</div>':''}</div><form class="chat-form" id="chat-form"><input id="chat-input" name="request" placeholder="Ask for a service or gift card…" aria-label="Message to spending assistant" maxlength="200" autocomplete="off" ${busy?'disabled':''}><button type="submit" aria-label="Send request" ${busy?'disabled':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m6 15 6-6 6 6M12 9v11"/></svg></button></form><p class="chat-caption">Live market overview: funded agent wallet + up to 5% fee and network gas. Other catalog items use demo funds. Also try “Check agent balance”, “Check my GFLD fee” or “Pause agent”.</p></section><aside class="side-column"><section class="panel"><div class="panel-title"><h2>Your rules</h2><button class="mini-link" data-tab="settings">Edit</button></div><div class="rules-summary"><div><span>Per purchase</span><b>${dollars(c.perBuy)}</b></div><div><span>Per day</span><b>${dollars(c.perDay)}</b></div><div><span>Ask me above</span><b>${dollars(c.askAbove)}</b></div></div><div class="category-pills">${c.categories.map(x=>`<span>${x}</span>`).join('')||'<span>No categories allowed</span>'}</div></section>${scheduleSummary(c)}${activityPanel()}</aside></div>`;}
function shop(){return`<div class="panel-title"><h2>The shop</h2><span>Demo catalog + live market overview</span></div><div class="shop-grid">${catalog.map(i=>`<article class="shop-item"><span class="service-icon" style="--service:${i.color}">${i.icon}</span><h3>${i.name}</h3><small>${i.category}</small><p>${i.description}</p><div class="item-bottom"><strong>${dollars(i.price)}</strong><button class="btn secondary small" data-item="${i.id}">Try purchase</button></div>${i.id==='market'?'<button class="mini-link" data-live-quote style="margin-top:18px">Buy a live market overview ↗</button>':''}</article>`).join('')}</div>`;}
function demoOrders(c,onlyPending){const list=state.orders.filter(o=>o.cardId===c.id&&(!onlyPending||o.status==='pending'));if(!list.length)return`<div class="empty-state"><span>${onlyPending?'✓':'◷'}</span><h2>${onlyPending?'Nothing waiting for you.':'Your first receipt is a purchase away.'}</h2><p>${onlyPending?'Purchases above your approval threshold appear here. Their amount is held until you approve, decline or cancel.':'Try a purchase from the demo shop. Completed orders, approvals and cancelled orders stay here.'}</p><button class="btn secondary small" data-tab="shop">Explore the demo shop</button></div>`;return`<div class="panel-title"><h2>${onlyPending?'Waiting for your approval':'Orders & receipts'}</h2><span>${list.length} ${list.length===1?'order':'orders'}</span></div><div class="order-list">${list.map(o=>{const i=catalog.find(i=>i.id===o.itemId);return`<article class="order-card"><span class="service-icon" style="--service:${i.color}">${i.icon}</span><div><h3>${esc(o.name)}</h3><span class="badge ${o.status}">${o.status==='pending'?'Awaiting approval':o.status==='completed'?'Demo purchase complete':o.status}</span><p>${new Date(o.createdAt).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${esc(c.name)}</p>${o.status==='pending'?`<p class="pending-note">${dollars(o.amount)} is reserved. No real payment has been made.</p><div class="order-actions"><button class="btn leaf small" data-resolve="approve" data-order="${o.id}">Approve demo purchase</button><button class="btn secondary small" data-resolve="decline" data-order="${o.id}">Decline</button><button class="mini-link" data-resolve="cancel" data-order="${o.id}">Cancel order</button></div>`:o.status==='completed'?`<code class="receipt-code">${esc(o.receipt)}</code><p>Sample only. This receipt cannot be redeemed.</p><div class="order-actions"><button class="mini-link" data-receipt="${o.id}">Open receipt</button></div>`:'<p>The hold was released. No demo funds were spent.</p>'}</div><strong>${dollars(o.amount)}</strong></article>`;}).join('')}</div>`;}
function settings(c){return`<div class="settings-layout"><section class="panel"><div class="panel-title"><h2>Spending rules</h2><span>Checked on every purchase</span></div><form id="rules-form"><div class="form-fields"><div class="field"><label for="rule-name">Card name</label><input id="rule-name" name="name" value="${esc(c.name)}" maxlength="32" required></div><div class="field-row"><div class="field"><label for="rule-buy">Per purchase · $</label><input id="rule-buy" name="perBuy" type="number" min="1" step=".01" value="${c.perBuy/100}" required></div><div class="field"><label for="rule-day">Per day · $</label><input id="rule-day" name="perDay" type="number" min="1" step=".01" value="${c.perDay/100}" required></div></div><div class="field"><label for="rule-ask">Ask me above · $</label><input id="rule-ask" name="askAbove" type="number" min="0" step=".01" value="${c.askAbove/100}" required><small>Use $0 to approve every purchase. Purchases at or below this amount complete automatically.</small></div><fieldset style="border:0;padding:0;margin:0"><legend style="font-size:11px;color:#8e9f7b;margin-bottom:12px">Allowed categories</legend><div class="category-checks">${categories.map(x=>`<label><input type="checkbox" name="category" value="${x}" ${c.categories.includes(x)?'checked':''}>${x}</label>`).join('')}</div></fieldset></div><p class="form-error" id="rules-error" role="alert"></p><div class="form-actions"><button class="btn small" type="submit">Save rules</button></div></form></section><aside><div class="hint-box" style="margin-top:0"><b>Your limits travel with the card.</b>Purchases are checked against available balance, daily spending and pending approvals. Each card has its own budget.</div><div class="hint-box"><b>No partial orders.</b>If a full purchase is unavailable or exceeds a limit, nothing is spent. The demo never buys a smaller substitute.</div><div class="hint-box"><b>Pause whenever you want.</b>Freezing blocks purchases and approvals. You can still cancel a pending order and release its hold.</div></aside></div>`;}
const agentWalletViews={};
function connector(){
 const c=card(),grant=state.agents?.[c.id],wallet=agentWalletViews[c.id];
 const active=grant?.enabled&&grant.validUntil>Date.now();
 const withdrawals=(state.agentWithdrawals||[]).filter(w=>w.cardId===c.id).slice(0,5);
 return `<section class="panel" style="max-width:720px"><div class="panel-title"><h2>Connect your own AI</h2><span>${active?'Agent enabled':'Agent wallet'}</span></div>
 <p class="chat-intro">Give your agent a separate funded wallet. Grantfold signs purchases within your consent and this card’s rules. Its wallet key is encrypted on the server.</p>
 <div class="connector-tabs"><button class="active" data-client="ChatGPT">ChatGPT</button><button data-client="Claude">Claude</button><button data-client="Cursor">Cursor</button></div>
 <pre class="connector-code" id="connector-preview">Client: Grantfold Assistant\nNetwork: Robinhood Chain\nCard: ${esc(c.name)}\nTools: wallet · buy market overview · recover order\nMode: ${active?'Ready: return to Assistant and request a live market overview':'Set up and fund a wallet, then return to Assistant'}</pre>
 ${grant?`<div class="hint-box"><b>Agent deposit address · USDG + ETH on Robinhood Chain</b><code style="overflow-wrap:anywhere">${esc(grant.address)}</code><p style="margin-top:10px">${wallet?`${usdg(Number(wallet.usdgMicros))} · ${Number(wallet.ethWei)/1e18} ETH`:'Refresh to read the wallet’s live balances.'}</p><p style="margin-top:10px">${active?'Consent valid until '+new Date(grant.validUntil).toLocaleString():'New autonomous purchases are disabled.'}</p></div>`:''}
 <div class="hint-box"><b>Up to 5% service fee, with no minimum.</b>${feePolicy?.enabled?`${tokenLink('GFLD holder fees')}: ${gfldTiersText}. The linked owner’s balance is checked for each new quote.`:`Token fee discounts are currently inactive. ${tokenLink('View GFLD')}.`} The total includes the provider price and Grantfold fee. The client supplies the wallet’s USDG and ETH. Network gas is capped at 0.00001 ETH per transaction and 0.0001 ETH per UTC day for autonomous purchases. Orders above your approval threshold wait for you.</div>
 <div class="form-actions" style="flex-wrap:wrap">${active?'<button class="btn secondary small" data-agent-revoke>Pause agent</button>':'<button class="btn small" data-agent-setup>'+ (grant?'Renew consent':'Set up agent wallet')+'</button>'}${grant?'<button class="btn secondary small" data-agent-refresh>Refresh balances</button><button class="btn secondary small" data-agent-withdraw>Return funds</button>':''}</div>
 ${scheduleSummary(c)}
 ${withdrawals.length?`<div class="activity-list" style="margin-top:24px">${withdrawals.map(w=>`<div class="activity-item"><div style="min-width:0"><b>Return ${esc(w.asset)} · ${esc(w.status)}</b><small style="overflow-wrap:anywhere">${esc(w.transaction||w.to)}</small></div>${w.status==='prepared'?`<button class="mini-link" data-agent-withdraw-open="${w.id}">Review</button>`:w.status==='checking'?`<button class="mini-link" data-agent-withdraw-check="${w.id}">Check</button>`:''}</div>`).join('')}</div>`:''}
 </section>`;
}
async function signOwnerIntent(data,expected){const owner=await connectLiveWallet();if(owner.toLowerCase()!==expected.toLowerCase())throw Error('Connect the linked owner wallet.');return window.ethereum.request({method:'eth_signTypedData_v4',params:[owner,JSON.stringify(data)]});}
function agentConsentModal(setup){
 openModal(`<span class="pill">Agent spending consent</span><h2 id="dialog-title">Approve a separate budget.</h2><p>Grantfold will hold this wallet’s encrypted signing key and can buy the live market overview from its funded balance.</p><div class="hint-box"><b>${usdg(setup.perBuyMicros)} per purchase · ${usdg(setup.perDayMicros)} per day</b>Maximum 5% fee to ${esc(commission.recipient)}. Gas cap: 0.00001 ETH per transaction and 0.0001 ETH per UTC day. Consent expires ${new Date(setup.validUntil).toLocaleString()}. Pausing stops new purchases; submitted orders can finish.</div><p style="margin-top:16px">After consent, fund only the budget you want the agent to use. USDG pays for purchases and fees; ETH pays network gas. Read <a href="/terms" target="_blank" rel="noopener noreferrer">Terms</a>, <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy</a> and <a href="/support" target="_blank" rel="noopener noreferrer">Support</a> before authorizing.</p><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Cancel</button><button class="btn small" data-agent-enable="${setup.cardId}">Authorize agent</button></div>`);
}
function withdrawalModal(w){
 const display=Number(w.amount)/(w.asset==='USDG'?1e6:1e18);
 openModal(`<span class="pill">Return agent funds</span><h2 id="dialog-title">Return ${display} ${esc(w.asset)}.</h2><p>Funds go only to the linked owner wallet. The agent wallet pays its network gas, capped at 0.00001 ETH for this return. New autonomous purchases are paused.</p><div class="hint-box"><b>Receiving wallet</b><code style="overflow-wrap:anywhere">${esc(w.to)}</code></div><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Close</button><button class="btn small" data-agent-withdraw-sign="${w.id}">Sign return request</button><button class="mini-link" data-agent-withdraw-cancel="${w.id}">Cancel return</button></div>`);
}
async function handleAgentClick(el){
 const known=Object.keys(el.dataset).some(k=>k.startsWith('agent'));
 if(!known)return false;if(networkBusy||liveWalletBusy)return true;liveWalletBusy=true;el.disabled=true;
 try{
  const cardId=card().id;
  if(el.hasAttribute('data-agent-setup')){const owner=await connectLiveWallet();const effect=await mutate({cardId,owner},'/api/agent/prepare');agentConsentModal(effect.setup);}
  else if(el.dataset.agentEnable){const setup=state.agentSetups[el.dataset.agentEnable];const signature=await signOwnerIntent(consentTypedData(setup,location.origin),setup.owner);await mutate({cardId:setup.cardId,signature},'/api/agent/enable');closeModal();render();toast('Agent enabled. Add USDG and ETH to its separate wallet.');}
  else if(el.hasAttribute('data-agent-revoke')){await mutate({cardId},'/api/agent/revoke');render();toast('New autonomous purchases paused.');}
  else if(el.hasAttribute('data-agent-refresh')){const data=await apiRequest('/api/agent/status',{cardId});applySnapshot(data);agentWalletViews[cardId]=data.wallet;render();}
  else if(el.dataset.agentBuy){await mutate({orderId:el.dataset.agentBuy},'/api/agent/check');render();liveOrderModal(findLive(el.dataset.agentBuy));}
  else if(el.dataset.agentApprove){await mutate({orderId:el.dataset.agentApprove},'/api/agent/approve');render();liveOrderModal(findLive(el.dataset.agentApprove));}
  else if(el.hasAttribute('data-agent-withdraw')){openModal(`<span class="pill">Return funded balance</span><h2 id="dialog-title">Back to your wallet.</h2><p>Preparing a return pauses the agent. Only the linked owner can sign it.</p><form id="agent-withdraw-form"><div class="field"><label>Asset</label><select name="asset"><option>USDG</option><option>ETH</option></select></div><div class="field"><label>Amount</label><input name="amount" inputmode="decimal" required placeholder="0.50"></div><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn small" type="submit">Review return</button></div></form>`);}
  else if(el.dataset.agentWithdrawOpen){withdrawalModal(state.agentWithdrawals.find(w=>w.id===el.dataset.agentWithdrawOpen));}
  else if(el.dataset.agentWithdrawSign){const w=state.agentWithdrawals.find(w=>w.id===el.dataset.agentWithdrawSign);const signature=await signOwnerIntent(withdrawalTypedData(w,location.origin),w.to);await mutate({withdrawalId:w.id,signature},'/api/agent/withdraw');closeModal();render();toast('Return submitted. Check its saved transaction.');}
  else if(el.dataset.agentWithdrawCancel){await mutate({withdrawalId:el.dataset.agentWithdrawCancel},'/api/agent/withdraw_cancel');closeModal();render();}
  else if(el.dataset.agentWithdrawCheck){await mutate({withdrawalId:el.dataset.agentWithdrawCheck},'/api/agent/withdraw_check');render();}
 }catch(e){if($('#live-error'))$('#live-error').textContent=e.code===4001?'Wallet request cancelled.':e.message;else toast(e.message);}
 finally{liveWalletBusy=false;el.disabled=false;}return true;
}
document.addEventListener('submit',async e=>{if(e.target.id!=='agent-withdraw-form')return;e.preventDefault();if(networkBusy)return;const d=new FormData(e.target);try{const effect=await mutate({cardId:card().id,asset:String(d.get('asset')),amount:String(d.get('amount'))},'/api/agent/withdraw_prepare');withdrawalModal(effect.withdrawal);}catch(error){$('#live-error').textContent=error.message;}});

function scheduleWindow(hour){return String(hour).padStart(2,'0')+':00–'+String(hour).padStart(2,'0')+':59 UTC';}
function scheduleSummary(c){
 const p=state.schedules?.[c.id],open=p?.currentRun?.orderId||p?.lastOrderId;
 return `<div class="hint-box"><b>Daily market overview ${p?'· '+esc(p.status.replaceAll('_',' ')):''}</b>${p?`${scheduleWindow(p.utcHour)} · cap ${usdg(p.maxTotalMicros)} per attempt · ${p.completedRuns}/${p.maxRuns} delivered.<br>${esc(p.message||'')}<br>Consent expires ${new Date(p.validUntil).toLocaleString()}. ${['active','running'].includes(p.status)?'Next window: '+new Date(p.nextRunAt).toLocaleString()+'.':''}`:'Authorize a daily purchase with a price cap and run limit. It can run while this page is closed.'}<div class="order-actions" style="margin-top:12px">${!p||(['paused','completed','expired'].includes(p.status)&&!p.currentRun)?'<button class="mini-link" data-schedule-open>Configure schedule</button>':'<button class="mini-link" data-schedule-pause>Pause schedule</button>'}${open?`<button class="mini-link" data-live-open="${esc(open)}">View saved order</button>`:''}</div></div>`;
}
function scheduleFormModal(){
 const c=card(),g=state.agents?.[c.id];
 if(!schedulingCapabilities?.configured){openModal('<span class="pill">Daily purchases</span><h2 id="dialog-title">Scheduler unavailable.</h2><p>Daily purchases are not configured on this deployment. Your wallet permissions have not changed.</p>');return;}
 if(!g?.enabled||g.validUntil<=Date.now()||g.site!==location.origin){openModal('<span class="pill">Daily purchases</span><h2 id="dialog-title">Enable your agent first.</h2><p>Daily purchases need a current agent consent signed on this website, then a separate signed schedule. Open Connect AI to set up or renew the consent.</p><div class="form-actions"><button class="btn small" data-schedule-connect>Open Connect AI</button></div>');return;}
 openModal(`<span class="pill">Daily market overview</span><h2 id="dialog-title">Set your daily window.</h2><p>One Agent402 market overview per day, within a selected UTC hour. Timing can vary within that hour. Missed windows are skipped; purchases are never caught up in a batch.</p><form id="schedule-form" data-card-id="${esc(c.id)}"><div class="field"><label for="schedule-hour">Daily window · UTC</label><select id="schedule-hour" name="utcHour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===9?'selected':''}>${scheduleWindow(h)}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label for="schedule-cap">Maximum total per purchase · USDG</label><input id="schedule-cap" name="cap" inputmode="decimal" value="0.02" required></div><div class="field"><label for="schedule-runs">Maximum purchase attempts · 1–7</label><input id="schedule-runs" name="maxRuns" type="number" min="1" max="7" value="3" required></div></div><div class="hint-box">The cap includes the provider price and Grantfold fee. ETH gas is separate and remains capped by your agent consent. The schedule cannot outlive that consent or bypass card rules and approvals. The first window is in the future.</div><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" type="button" data-action="close-modal">Cancel</button><button class="btn small" type="submit">Review daily purchases</button></div></form>`);
}
function scheduleConsentModal(p){
 openModal(`<span class="pill">Recurring spending permission</span><h2 id="dialog-title">Authorize daily purchases.</h2><p>Your agent can buy a market overview without this page being open. This is a separate permission for repeated payments.</p><div class="hint-box"><b>${scheduleWindow(p.utcHour)} · up to ${p.maxRuns} purchase attempts</b>Maximum ${usdg(p.maxTotalMicros)} per purchase, including the fee; maximum ${usdg(p.maxTotalMicros*p.maxRuns)} for all attempts. ETH gas is separate, capped at 0.00001 ETH per transaction and 0.0001 ETH per UTC day.<br>First window: ${new Date(p.firstRunAt).toLocaleString()}.<br>Consent expires ${new Date(p.validUntil).toLocaleString()}.<br>Agent wallet: <code style="overflow-wrap:anywhere">${esc(p.agent)}</code>.</div><p style="margin-top:16px">The current GFLD fee tier is checked for each new run. Above-threshold orders wait for approval. Pause schedule or Pause agent stops new runs; already submitted orders and their agreed fees can finish. <a href="/terms" target="_blank" rel="noopener noreferrer">Terms</a> · <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy</a></p><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Cancel</button><button class="btn small" data-schedule-sign="${esc(p.cardId)}">Sign schedule</button></div>`);
}
async function handleScheduleClick(el){
 if(!Object.keys(el.dataset).some(k=>k.startsWith('schedule')))return false;
 if(networkBusy||liveWalletBusy)return true;
 if(el.hasAttribute('data-schedule-connect')){closeModal();tab='connect';render();return true;}
 if(el.hasAttribute('data-schedule-open')){scheduleFormModal();return true;}
 liveWalletBusy=true;el.disabled=true;
 try{
  if(el.dataset.scheduleSign){const p=state.scheduleSetups?.[el.dataset.scheduleSign];if(!p)throw Error('Review a fresh schedule.');const signature=await signOwnerIntent(scheduleTypedData(p),p.owner);await mutate({cardId:p.cardId,signature},'/api/schedule/enable');closeModal();render();toast('Daily purchases authorized. The first window is in the future.');}
  else if(el.hasAttribute('data-schedule-pause')){await mutate({cardId:card().id},'/api/schedule/pause');render();toast('New scheduled purchases paused.');}
 }catch(e){if($('#live-error'))$('#live-error').textContent=e.code===4001?'Schedule signature cancelled.':e.message;else toast(e.message);}
 finally{liveWalletBusy=false;el.disabled=false;}return true;
}
document.addEventListener('submit',async e=>{
 if(e.target.id!=='schedule-form')return;e.preventDefault();if(networkBusy||liveWalletBusy)return;
 const data=new FormData(e.target),raw=String(data.get('cap')).trim();
 try{
  if(!/^\d{1,6}(?:\.\d{1,6})?$/.test(raw))throw Error('Use a positive USDG cap with up to six decimals.');
  const [whole,fraction='']=raw.split('.'),maxTotalMicros=Number(BigInt(whole)*1000000n+BigInt(fraction.padEnd(6,'0')));
  const effect=await mutate({cardId:e.target.dataset.cardId,utcHour:Number(data.get('utcHour')),maxRuns:Number(data.get('maxRuns')),maxTotalMicros},'/api/schedule/prepare');scheduleConsentModal(effect.setup);
 }catch(error){$('#live-error').textContent=error.message;}
});

const feePercent=o=>(o.feeBps??commission.bps)/100;
const findLive=id=>state.liveOrders?.find(o=>o.id===id);
let liveWalletBusy=false;
function liveOrdersHTML(c,onlyPending){
 const list=(state.liveOrders||[]).filter(o=>o.cardId===c.id&&(!onlyPending||liveHeld(o)));if(!list.length)return'';
 return `<div class="panel-title" style="margin-top:28px"><h2>Live market purchases</h2><span>USDG · Robinhood Chain</span></div><div class="order-list">${list.map(o=>{
  const expired=['quoted','ready','agent_approval'].includes(o.status)&&o.expiresAt<=Date.now(),status=expired?'expired':o.status;let action='';
  if(status==='completed')action=`<button class="mini-link" data-live-open="${o.id}">Open report & receipt</button>`;
  else if(status==='agent_approval')action=`<button class="btn small" data-agent-approve="${o.id}">Approve agent purchase</button><button class="mini-link" data-live-cancel="${o.id}">Cancel</button>`;
  else if(o.agent&&['quoted','ready'].includes(status))action=`<button class="btn secondary small" data-live-open="${o.id}">Review agent purchase</button>`;
  else if(o.agent&&['quoted','ready','processing','checking','needs_review','fee_due','fee_checking'].includes(status))action=`<button class="btn secondary small" data-live-check="${o.id}">Resume agent purchase</button>`;
  else if(['processing','checking','needs_review'].includes(status))action=`<button class="btn secondary small" data-live-check="${o.id}">Check payment</button>`;
  else if(['quoted','ready','fee_due','fee_checking'].includes(status))action=`<button class="btn secondary small" data-live-open="${o.id}">${status.startsWith('fee_')?'Review fee':'Review quote'}</button>`;
  return `<article class="order-card"><span class="service-icon" style="--service:#dfe8f5">∿</span><div><h3>${esc(o.name)}</h3><span class="badge ${status==='completed'?'completed':'pending'}">${esc(status.replaceAll('_',' '))}</span><p>Agent402 · ${o.agent?'agent wallet':'your wallet'}</p><p>${esc(o.message||'Review the live quote and authorize the exact amount.')}</p><div class="order-actions">${action}</div></div><strong>${usdg(orderTotal(o))}</strong></article>`;
 }).join('')}</div>`;
}
function orders(c,onlyPending){const live=liveOrdersHTML(c,onlyPending),scheduled=onlyPending?'':scheduleActivityHTML(state,c.id),hasDemo=state.orders.some(o=>o.cardId===c.id&&(!onlyPending||o.status==='pending'));return scheduled+((live||scheduled)&&!hasDemo?'':demoOrders(c,onlyPending))+live;}
function liveOrderModal(o){if(!o)return;const expired=o.expiresAt<=Date.now(),short=a=>a.slice(0,6)+'…'+a.slice(-4);let content='';
 if(o.status==='completed'){content=`<div class="success-icon">✓</div><span class="pill">Live report delivered</span><h2 id="dialog-title">Your market overview.</h2><p>${usdg(o.amountMicros)} paid from ${esc(short(o.authorization.from))} to Agent402 on Robinhood Chain.</p><div class="activity-list">${o.report.coins.map(c=>`<div class="activity-item"><div><b>${esc(c.name)} · ${esc(c.symbol.toUpperCase())}</b><small>24h: ${c.change24hPct===null?'—':c.change24hPct.toFixed(2)+'%'}</small></div><strong style="margin-left:auto">$${c.price.toLocaleString('en-US',{maximumFractionDigits:6})}</strong></div>`).join('')}</div><p style="font-size:11px;margin-top:18px">${esc(o.report.credit)}</p><div class="hint-box"><b>Payment verified on Robinhood Chain.</b><a href="${liveMarket.explorer}/tx/${o.receipt.transaction}" target="_blank" rel="noopener noreferrer">View provider transaction ↗</a>${o.feeReceipt?`<p style="margin-top:10px">Grantfold ${feePercent(o)}%: ${usdg(o.feeMicros)} · <a href="${liveMarket.explorer}/tx/${o.feeReceipt.transaction}" target="_blank" rel="noopener noreferrer">View fee transaction ↗</a></p>`:''}</div><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Close</button><button class="btn small" data-action="view-activity">View history</button></div>`;
 }else if(['fee_due','fee_checking'].includes(o.status)){content=`<span class="pill">Service fee · Robinhood Chain</span><h2 id="dialog-title">Finish this purchase.</h2><p>The provider delivery is saved. The total is ${usdg(orderTotal(o))}, including the ${usdg(o.feeMicros)} Grantfold fee.</p><div class="hint-box"><b>${feePercent(o)}% fee, no minimum.</b>${o.agent?'Your agent wallet pays the fee and network gas from its own balance.':'The paying wallet submits the fee transaction and pays its ETH network gas. The fee authorization can transfer this amount only once.'}</div><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Close</button>${!o.agent&&!o.feeBroadcastAt?`<button class="btn small" data-live-fee="${o.id}">Pay fee ${usdg(o.feeMicros)}</button>`:`<button class="btn small" data-live-check="${o.id}">Check fee</button>`}</div>`;
 }else if(['processing','checking','needs_review'].includes(o.status)){content=`<span class="pill">Live payment · ${esc(o.status.replaceAll('_',' '))}</span><h2 id="dialog-title">Check the same payment.</h2><p>${esc(o.message)}</p><div class="modal-receipt">${usdg(o.amountMicros)}</div><div class="hint-box">Your saved authorization is reused. No new wallet signature or second purchase is needed. Reference: ${esc(o.id)}</div><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Close</button><button class="btn small" data-live-check="${o.id}">Check payment</button></div>`;
 }else if(o.agent&&['quoted','ready','agent_approval'].includes(o.status)&&!expired){content=`<span class="pill">Live agent purchase · Agent402</span><h2 id="dialog-title">Buy with your agent wallet.</h2><p>One market overview covering the top 10 coins. Your agent signs the payment within your existing consent and this card’s rules.</p><div class="order-summary"><span class="service-icon" style="--service:#dfe8f5">∿</span><div><b>Crypto market overview</b><small>USDG · Robinhood Chain</small></div><strong>${usdg(orderTotal(o))}</strong></div><div class="hint-box"><b>Provider: ${usdg(o.amountMicros)} · Grantfold ${feePercent(o)}%: ${usdg(o.feeMicros)}</b>Total: ${usdg(orderTotal(o))}, plus ETH network gas from the agent wallet, capped at 0.00001 ETH per transaction. Funded wallet: <code style="overflow-wrap:anywhere">${esc(state.agents?.[o.cardId]?.address||'unavailable')}</code>.${o.status==='agent_approval'?' This order exceeds your automatic approval threshold.':''}</div><p style="font-size:11px;margin-top:14px">Quote expires at ${new Date(o.expiresAt).toLocaleTimeString()}. By purchasing, you agree to <a href="/terms" target="_blank" rel="noopener noreferrer">Grantfold’s terms</a> and use <a href="https://agent402.tools/terms" target="_blank" rel="noopener noreferrer">Agent402’s terms</a>.</p><p class="form-error" id="live-error" role="alert"></p><div class="form-actions" style="flex-wrap:wrap"><button class="btn secondary small" data-live-cancel="${o.id}">Cancel quote</button><button class="btn small" ${o.status==='agent_approval'?'data-agent-approve':'data-agent-buy'}="${o.id}">${o.status==='agent_approval'?'Approve agent purchase':'Buy with agent wallet'} · ${usdg(orderTotal(o))}</button></div>`;
 }else if(['quoted','ready'].includes(o.status)&&!expired){content=`<span class="pill">Live purchase · Agent402</span><h2 id="dialog-title">Crypto market overview.</h2><p>Current prices, market caps and 24-hour changes for the top 10 coins.</p><div class="order-summary"><span class="service-icon" style="--service:#dfe8f5">∿</span><div><b>One market overview</b><small>USDG · Robinhood Chain</small></div><strong>${usdg(orderTotal(o))}</strong></div><div class="hint-box"><b>Paid directly from your wallet.</b>Demo funds are separate. ${o.feeMicros?`Provider: ${usdg(o.amountMicros)}. Grantfold ${feePercent(o)}%: ${usdg(o.feeMicros)}. Total: ${usdg(orderTotal(o))}. ETH is needed for the fee’s network gas, capped at 0.00001 ETH per transaction.`:'Grantfold fee: 0 USDG.'} Your wallet authorizes this exact amount once, with no token allowance. ${o.authorization?'Wallet: '+esc(short(o.authorization.from))+'.':'Connect a wallet holding USDG on Robinhood Chain.'}</div><p style="font-size:11px;margin-top:14px">Quote expires at ${new Date(o.expiresAt).toLocaleTimeString()}. By purchasing, you agree to <a href="/terms" target="_blank" rel="noopener noreferrer">Grantfold’s terms</a> and use <a href="https://agent402.tools/terms" target="_blank" rel="noopener noreferrer">Agent402’s terms</a>.</p><p class="form-error" id="live-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-live-cancel="${o.id}">Cancel quote</button>${o.status==='ready'?`<button class="btn small" data-live-pay="${o.id}">Authorize ${usdg(orderTotal(o))}</button>`:`<button class="btn small" data-live-connect="${o.id}">Connect wallet</button>`}</div>`;
 }else{content=`<span class="pill">Live quote · ${expired?'expired':esc(o.status)}</span><h2 id="dialog-title">${expired?'Request a fresh price.':'This order is closed.'}</h2><p>${esc(o.message||'No payment was submitted through Grantfold for this quote.')}</p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Close</button></div>`;}openModal(content);}
async function liveAction(path,body){return mutate(body,'/api/live/'+path);}
async function handleLiveClick(el){const id=el.dataset.liveOpen||el.dataset.liveConnect||el.dataset.livePay||el.dataset.liveCheck||el.dataset.liveCancel;if(!el.hasAttribute('data-live-quote')&&!id)return false;if(networkBusy||liveWalletBusy)return true;
 try{
  if(el.dataset.liveOpen){liveOrderModal(findLive(id));return true;}
  if(el.hasAttribute('data-live-quote')){const effect=await liveAction('quote',{cardId:card().id});liveOrderModal(findLive(effect.orderId));return true;}
  if(el.dataset.liveCancel){await liveAction('cancel',{orderId:id});closeModal();render();return true;}
  if(el.dataset.liveConnect){liveWalletBusy=true;el.disabled=true;const wallet=await connectLiveWallet();await liveAction('prepare',{orderId:id,wallet});liveOrderModal(findLive(id));return true;}
  if(el.dataset.livePay){liveWalletBusy=true;el.disabled=true;const payment=await signLiveOrder(findLive(id));await liveAction('pay',{orderId:id,...(typeof payment==='string'?{signature:payment}:payment)});render();liveOrderModal(findLive(id));return true;}
  if(el.dataset.liveCheck){el.disabled=true;if(findLive(id)?.agent)await mutate({orderId:id},'/api/agent/check');else if(['fee_due','fee_checking'].includes(findLive(id)?.status))await liveAction('fee_check',{orderId:id});else await liveAction('check',{orderId:id});render();liveOrderModal(findLive(id));return true;}
 }catch(error){const message=error.code===4001||error.code==='ACTION_REJECTED'?'Wallet request cancelled. No new payment was submitted.':error.message;if($('#live-error'))$('#live-error').textContent=message;else toast(message);}
 finally{liveWalletBusy=false;el.disabled=false;}
 return true;
}


async function handleFeeClick(el){
 if(!el.dataset.liveFee)return false;if(networkBusy||liveWalletBusy)return true;liveWalletBusy=true;el.disabled=true;const id=el.dataset.liveFee;
 try{const order=findLive(id),wallet=await connectLiveWallet();if(wallet.toLowerCase()!==order.authorization.from.toLowerCase())throw Error('Connect the wallet that paid for this order.');
  const effect=await liveAction('fee_transaction',{orderId:id});if(effect.transaction){let hash;try{hash=await window.ethereum.request({method:'eth_sendTransaction',params:[effect.transaction]});}catch(e){if(e.code===4001)await liveAction('fee_declined',{orderId:id});throw e;}await liveAction('fee_check',{orderId:id,transaction:hash});}
  render();liveOrderModal(findLive(id));
 }catch(e){if($('#live-error'))$('#live-error').textContent=e.code===4001?'Fee transaction cancelled.':e.message;else toast(e.message);}finally{liveWalletBusy=false;el.disabled=false;}return true;
}

function render(){const isApp=location.hash.startsWith('#/app');document.title=isApp?'Grantfold · Agent spending sandbox':'Grantfold — Cards for your RH agents';app.innerHTML=isApp?(ready?renderApp():accountGate()):home();}
function openModal(html){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="icon-button close" data-action="close-modal" aria-label="Close dialog">×</button>${html}</section></div>`;$('.modal input')?.focus();if(!$('.modal input'))$('.modal button')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus();}
function receiptModal(o){openModal(`<div class="success-icon">✓</div><span class="pill">Demo receipt</span><h2 id="dialog-title">${esc(o.name)} is ready.</h2><p>This is a sample purchase. No real product, card or redeemable code has been issued.</p><div class="modal-receipt">${dollars(o.amount)}</div><code class="receipt-code">${esc(o.receipt)}</code><div class="hint-box">Saved to this card’s Activity in your Grantfold account.</div><div class="form-actions"><button class="btn small" data-action="view-activity">View receipt history</button></div>`);}
async function doPurchase(itemId){try{const effect=await mutate({type:'purchase',cardId:card().id,itemId});closeModal();if(effect.status==='pending'){tab='approvals';render();const o=state.orders.find(o=>o.id===effect.orderId);toast('Approval requested. '+dollars(o.amount)+' reserved.');}else{render();receiptModal(state.orders.find(o=>o.id===effect.orderId));}}catch(e){if($('#purchase-error'))$('#purchase-error').textContent=e.message;else toast(e.message);}}
async function ask(text){text=text.trim();if(!text||busy||networkBusy)return;const cardId=card().id;let effect;busy=true;render();try{effect=await mutate({type:'assistant',cardId,text});}catch(e){toast(e.message);}finally{busy=false;render();$('#chat-messages')?.scrollTo({top:10000,behavior:'smooth'});if(effect?.live)liveOrderModal(findLive(effect.orderId));}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.scroll){e.preventDefault();$('#'+el.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('.mobile-menu')?.classList.remove('open');return;}
 const a=el.dataset.action;
 if(a==='wallet-login'){if(networkBusy)return;networkBusy=true;el.disabled=true;try{await signInWithWallet(apiRequest);await loadAccount();}catch(error){toast(error.code===4001?'Wallet login cancelled.':error.message);}finally{networkBusy=false;el.disabled=false;}return;}
 if(a==='wallet-signout'){if(networkBusy)return;await apiRequest('/api/auth/logout',{});ready=false;sessionUser=null;revision=-1;state=initialState();await loadAccount();return;}
 if(a==='retry-account'||a==='skip-backup'){skipLegacy=a==='skip-backup'||skipLegacy;await loadAccount();return;}
 if(el.dataset.tab){tab=el.dataset.tab;render();return;}
 if(el.dataset.card){state.selected=el.dataset.card;rememberSelection();render();return;}
 if(el.dataset.how!==undefined){howStep=Number(el.dataset.how);document.querySelectorAll('[data-how]').forEach(b=>{const on=Number(b.dataset.how)===howStep;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);});$('#how-panel').innerHTML=howPanel();return;}
 if(el.dataset.client){document.querySelectorAll('[data-client]').forEach(b=>b.classList.toggle('active',b===el));$('#connector-preview').textContent=`Client: ${el.dataset.client}\nNetwork: Robinhood Chain\nCard: ${card().name}\nTools: cards · balance · buy market overview · recover order\nMode: External clients are not connected. Use Assistant on this site.`;return;}
 if(a==='menu'){$('.mobile-menu').classList.toggle('open');el.setAttribute('aria-expanded',$('.mobile-menu').classList.contains('open'));return;}
 if(a==='close-modal'){closeModal();return;}
 if(a==='view-activity'){closeModal();tab='activity';render();return;}
 if(networkBusy||liveWalletBusy)return;
 if(await handleScheduleClick(el))return;
 if(await handleAgentClick(el))return;
 if(await handleFeeClick(el))return;
 if(await handleLiveClick(el))return;
 if(el.dataset.item){const i=catalog.find(i=>i.id===el.dataset.item);openModal(`<span class="pill">Demo checkout</span><h2 id="dialog-title">Review your purchase.</h2><p>Check the amount and rules before you continue.</p><div class="order-summary"><span class="service-icon" style="--service:${i.color}">${i.icon}</span><div><b>${i.name}</b><small>${i.category}</small></div><strong>${dollars(i.price)}</strong></div><div class="hint-box"><b>${i.price>card().askAbove?'Your approval is required.':'Within your automatic spending threshold.'}</b>${i.description} This is a simulated purchase; no real payment is made.</div><p id="purchase-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" data-action="close-modal">Cancel</button><button class="btn small" data-purchase="${i.id}">${i.price>card().askAbove?'Request approval':'Pay with demo balance'}</button></div>`);return;}
 if(el.dataset.purchase){await doPurchase(el.dataset.purchase);return;}
 if(el.dataset.request){await ask(el.dataset.request);return;}
 if(el.dataset.resolve){try{await mutate({type:'resolve',orderId:el.dataset.order,action:el.dataset.resolve});render();toast(el.dataset.resolve==='approve'?'Demo purchase approved. Receipt ready.':'Order '+(el.dataset.resolve==='cancel'?'cancelled':'declined')+'. Hold released.');}catch(err){toast(err.message);}return;}
 if(el.dataset.receipt){receiptModal(state.orders.find(o=>o.id===el.dataset.receipt));return;}
 if(el.dataset.fund){$('#fund-amount').value=el.dataset.fund;return;}
 if(a==='freeze'){try{const effect=await mutate({type:'freeze',cardId:card().id,frozen:!card().frozen});render();toast(effect.frozen?'Card frozen. New purchases are blocked.':'Card unfrozen.');}catch(err){toast(err.message);}return;}
 if(a==='new-card'){openModal(`<span class="pill">Agent spending account</span><h2 id="dialog-title">A card for your next agent.</h2><p>Name it now. Add demo funds and adjust its rules whenever you’re ready.</p><form id="new-card-form"><div class="field"><label for="new-card-name">Agent card name</label><input id="new-card-name" name="name" maxlength="32" placeholder="e.g. Coding agent" required></div><div class="hint-box"><b>Starts with a $0 demo balance.</b>Default rules: $50 per purchase, $100 per day, approval above $25.</div><p class="form-error" id="new-card-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" type="button" data-action="close-modal">Cancel</button><button class="btn small" type="submit">Create demo card</button></div></form>`);}
 if(a==='fund'){openModal(`<span class="pill">Demo funds only</span><h2 id="dialog-title">Top up ${esc(card().name)}.</h2><p>Add a test balance. This top-up makes no wallet charge.</p><form id="fund-form"><div class="row" style="margin-bottom:20px">${[25,50,100,250].map(v=>`<button class="btn secondary small" type="button" data-fund="${v}">$${v}</button>`).join('')}</div><div class="field"><label for="fund-amount">Amount · demo USDG</label><input type="number" id="fund-amount" name="amount" value="50" min="1" max="1000" step=".01" required></div><div class="hint-box">Card receives the full demo amount. No real token transfer or fee.</div><p class="form-error" id="fund-error" role="alert"></p><div class="form-actions"><button class="btn secondary small" type="button" data-action="close-modal">Cancel</button><button class="btn small" type="submit">Add demo funds</button></div></form>`);}
});
document.addEventListener('submit',async e=>{if(!['new-card-form','fund-form','rules-form','chat-form'].includes(e.target.id))return;e.preventDefault();if(networkBusy)return;const formId=e.target.id,data=new FormData(e.target);
 if(formId==='chat-form'){await ask(String(data.get('request')||''));return;}
 try{
  if(formId==='new-card-form'){const effect=await mutate({type:'new-card',name:String(data.get('name'))});state.selected=effect.cardId;rememberSelection();closeModal();tab='assistant';render();toast('Demo card created. Add funds to start.');}
  if(formId==='fund-form'){const n=Number(data.get('amount'))*100;if(Math.abs(n-Math.round(n))>1e-7)throw Error('Use up to two decimal places.');await mutate({type:'fund',cardId:card().id,amount:Math.round(n)});closeModal();render();toast('Demo funds added.');}
  if(formId==='rules-form'){const parse=x=>{const n=Number(data.get(x))*100;if(Math.abs(n-Math.round(n))>1e-7)throw Error('Use up to two decimal places.');return Math.round(n);};await mutate({type:'rules',cardId:card().id,name:String(data.get('name')).trim(),perBuy:parse('perBuy'),perDay:parse('perDay'),askAbove:parse('askAbove'),categories:data.getAll('category')});render();toast('Rules saved.');}
 }catch(err){const errorId=formId==='new-card-form'?'new-card-error':formId==='fund-form'?'fund-error':'rules-error';if($('#'+errorId))$('#'+errorId).textContent=err.message;else toast(err.message);}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.mobile-menu')?.classList.remove('open');}if(e.key==='Tab'&&$('.modal')){const xs=[...$('.modal').querySelectorAll('button,a,input,select')].filter(el=>!el.disabled),first=xs[0],last=xs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();if(requestedTab())tab=requestedTab();render();if(location.hash.startsWith('#/app')&&!ready&&!loading)loadAccount();window.scrollTo(0,0);});
async function refreshAccount(){if(!ready||networkBusy||busy||loading||document.hidden||!location.hash.startsWith('#/app')||$('.modal')||tab==='settings')return;try{const data=await apiRequest('/api/account');if(data.revision>revision){const notices=newScheduleNotifications(state.scheduleActivity,data.state.scheduleActivity);applySnapshot(data);render();if(notices.length){const latest=notices[0],name=state.cards.find(c=>c.id===latest.cardId)?.name||'Agent';toast(name+': '+latest.text+(notices.length>1?' '+notices.length+' new schedule events in Activity.':''));}}}catch(e){if(e.status===401){ready=false;accountError=e;closeModal();render();}}}
window.addEventListener('focus',refreshAccount);document.addEventListener('visibilitychange',refreshAccount);setInterval(refreshAccount,15000);
render();if(location.hash.startsWith('#/app'))loadAccount();

window.ethereum?.on?.('accountsChanged',async accounts=>{if(ready&&sessionUser?.address&&accounts?.[0]?.toLowerCase()!==sessionUser.address.toLowerCase()){try{await apiRequest('/api/auth/logout',{});}catch{}ready=false;sessionUser=null;revision=-1;state=initialState();await loadAccount();}});
